arguments.command:
cd /workspace && python3 -c "
import os
total=0; entries=0
for base,dirs,files in os.walk('submission'):
    for n in dirs+files:
        entries+=1
        p=os.path.join(base,n)
        if os.path.isfile(p) and not os.path.islink(p): total+=os.path.getsize(p)
print('entries',entries,'bytes',total, 'limit 2MiB', 2*1024*1024)
"
